use xiom.io;

fn first_and_last(v: &Vec[Int]) -> Int {
  if v.len() > 0 {
    return v[0] + v[v.len() - 1];
  }
  return 0;
}

fn clear_vec(v: &mut Vec[Int]) {
  while v.len() > 0 {
    v.pop();
  }
}

fn main() -> Int {
  var data = Vec[Int].new();
  data.push(10);
  data.push(20);
  data.push(30);
  let result = first_and_last(&data);
  clear_vec(&mut data);
  io.println(data.len().to_str());
  return result;
}
